  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  ADMIN\n  USER\n}\n\nenum KanaType {\n  HIRAGANA\n  KATAKANA\n}\n\nenum KanaKategori {\n  BASIC\n  DAKUTEN\n  HANDAKUTEN\n}\n\nenum JlptLevel {\n  N5\n  N4\n  N3\n  N2\n  N1\n}\n\nenum MateriType {\n  KOTOBA\n  KANJI\n  GRAMMAR\n}\n\n// Master data karakter kana, dikelola admin lewat /admin/kana\nmodel KanaChar {\n  id        String       @id @default(cuid())\n  karakter  String\n  romaji    String\n  jenis     KanaType\n  kategori  KanaKategori @default(BASIC)\n  createdAt DateTime     @default(now())\n\n  @@unique([karakter, jenis])\n}\n\nmodel User {\n  id           String   @id @default(cuid())\n  name         String\n  email        String   @unique\n  passwordHash String\n  role         Role     @default(USER)\n  createdAt    DateTime @default(now())\n\n  kotobaProgress  UserKotobaProgress[]\n  kanjiProgress   UserKanjiProgress[]\n  grammarProgress UserGrammarProgress[]\n  kanaProgress    UserKanaProgress[]\n  attempts        QuizAttempt[]\n}\n\n// Kotoba = kosakata, di-tag JLPT level + bab buku Minna no Nihongo\nmodel Kotoba {\n  id            String    @id @default(cuid())\n  kanjiKana     String\n  furigana      String?\n  romaji        String?\n  arti          String\n  contohKalimat String?\n  level         JlptLevel @default(N5)\n  bab           Int?\n  createdAt     DateTime  @default(now())\n  createdBy     String\n\n  progresses UserKotobaProgress[]\n}\n\n// Kanji tunggal dengan cara baca on'yomi/kun'yomi\nmodel Kanji {\n  id        String    @id @default(cuid())\n  karakter  String\n  onyomi    String?\n  kunyomi   String?\n  arti      String\n  level     JlptLevel @default(N5)\n  bab       Int?\n  createdAt DateTime  @default(now())\n  createdBy String\n\n  progresses UserKanjiProgress[]\n}\n\n// Pola tata bahasa (grammar point)\nmodel Grammar {\n  id            String    @id @default(cuid())\n  pola          String\n  penjelasan    String\n  contohKalimat String?\n  arti          String?\n  level         JlptLevel @default(N5)\n  bab           Int?\n  createdAt     DateTime  @default(now())\n  createdBy     String\n\n  progresses UserGrammarProgress[]\n}\n\n// --- Progress SRS berbasis FSRS (field mengikuti struktur Card dari ts-fsrs) ---\n// state: 0=New 1=Learning 2=Review 3=Relearning\n\nmodel UserKotobaProgress {\n  id       String @id @default(cuid())\n  userId   String\n  kotobaId String\n  user     User   @relation(fields: [userId], references: [id])\n  kotoba   Kotoba @relation(fields: [kotobaId], references: [id])\n\n  due           DateTime  @default(now())\n  stability     Float     @default(0)\n  difficulty    Float     @default(0)\n  elapsedDays   Int       @default(0)\n  scheduledDays Int       @default(0)\n  reps          Int       @default(0)\n  lapses        Int       @default(0)\n  state         Int       @default(0)\n  lastReview    DateTime?\n\n  @@unique([userId, kotobaId])\n}\n\nmodel UserKanjiProgress {\n  id      String @id @default(cuid())\n  userId  String\n  kanjiId String\n  user    User   @relation(fields: [userId], references: [id])\n  kanji   Kanji  @relation(fields: [kanjiId], references: [id])\n\n  due           DateTime  @default(now())\n  stability     Float     @default(0)\n  difficulty    Float     @default(0)\n  elapsedDays   Int       @default(0)\n  scheduledDays Int       @default(0)\n  reps          Int       @default(0)\n  lapses        Int       @default(0)\n  state         Int       @default(0)\n  lastReview    DateTime?\n\n  @@unique([userId, kanjiId])\n}\n\nmodel UserGrammarProgress {\n  id        String  @id @default(cuid())\n  userId    String\n  grammarId String\n  user      User    @relation(fields: [userId], references: [id])\n  grammar   Grammar @relation(fields: [grammarId], references: [id])\n\n  due           DateTime  @default(now())\n  stability     Float     @default(0)\n  difficulty    Float     @default(0)\n  elapsedDays   Int       @default(0)\n  scheduledDays Int       @default(0)\n  reps          Int       @default(0)\n  lapses        Int       @default(0)\n  state         Int       @default(0)\n  lastReview    DateTime?\n\n  @@unique([userId, grammarId])\n}\n\n// Progress belajar hiragana & katakana per karakter per user\nmodel UserKanaProgress {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id])\n  karakter  String\n  jenis     KanaType\n  benar     Int      @default(0)\n  salah     Int      @default(0)\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, karakter, jenis])\n}\n\n// Log tiap jawaban kuis (kotoba/kanji/grammar) -> dipakai untuk gap analysis per bab\nmodel QuizAttempt {\n  id         String     @id @default(cuid())\n  userId     String\n  user       User       @relation(fields: [userId], references: [id])\n  materiType MateriType\n  refId      String\n  bab        Int?\n  level      JlptLevel\n  benar      Boolean\n  responseMs Int\n  createdAt  DateTime   @default(now())\n\n  @@index([userId, materiType, bab])\n}\n",
